SELECT * FROM (
  SELECT o.*,
         ROW_NUMBER() OVER (
           PARTITION BY order_id
           ORDER BY source_ts DESC, lsn DESC, ingested_at DESC
         ) AS rn
  FROM bronze_orders_parsed o
) WHERE rn = 1;

{{ config(
    materialized='incremental',
    unique_key='order_id',
    incremental_strategy='merge',
    on_schema_change='append_new_columns'
) }}

select order_id, status, amount, updated_at, _ingested_at
from {{ ref('stg_shop__orders') }}
{% if is_incremental() %}
where _ingested_at > (select max(_ingested_at) from {{ this }})
{% endif %}
qualify row_number() over (
  partition by order_id order by updated_at desc, _ingested_at desc
) = 1
